/*
 * constants/index.js
 *
 * All static/config data lives here.
 * Components import from this file instead of hardcoding strings or arrays.
 * Makes future i18n, rebranding, or data changes trivial.
 */

/** Screen identifiers */
export const SCREENS = {
  WELCOME: 'welcome',
  AUTH:    'auth',
  CHAT:    'chat',
};

/** Mock users for the chat sidebar (replace with API data later) */
export const MOCK_USERS = [
  { id: '1', name: 'سارة أحمد',    initials: 'SA', lastMessage: 'مرحباً، كيف حالك؟',       time: '10:30', online: true  },
  { id: '2', name: 'عمر حسن',      initials: 'OH', lastMessage: 'أراك غداً!',              time: '09:15', online: true  },
  { id: '3', name: 'ليلى محمود',    initials: 'LM', lastMessage: 'شكراً على المساعدة 🙏', time: 'أمس', online: false },
  { id: '4', name: 'يوسف علي',     initials: 'YA', lastMessage: 'هل شاهدت الفيلم؟',      time: 'أمس', online: false },
  { id: '5', name: 'نور إبراهيم',   initials: 'NI', lastMessage: 'أخبرني عندما تكون متفرغاً', time: 'الإثنين', online: true  },
  { id: '6', name: 'هنا صالح',     initials: 'HS', lastMessage: 'إلى اللقاء!',            time: 'الأحد', online: false },
  { id: '7', name: 'جميل أحمد',    initials: 'JA', lastMessage: 'مرحباً، كيف حالك؟',       time: '10:30', online: true  },
];

/** Seed messages per conversation */
export const INITIAL_MESSAGES = {
  '1': [
    { id: 'm1', text: 'مرحباً! كيف حالك؟', sender: 'them', time: '10:28' },
    { id: 'm2', text: 'أنا بخير، شكراً! أعمل على المشروع الجديد.', sender: 'me', time: '10:29' },
    { id: 'm3', text: 'أهلاً، كيف حالك؟', sender: 'them', time: '10:30' },
  ],
  '2': [
    { id: 'm4', text: 'هل سنلتقي غداً؟', sender: 'me', time: '09:10' },
    { id: 'm5', text: 'نعم! نفس المكان كالمرّة الماضية.', sender: 'them', time: '09:12' },
    { id: 'm6', text: 'أراك غداً!', sender: 'them', time: '09:15' },
  ],
  '3': [
    { id: 'm7', text: 'هل تستطيع مساعدتي في صفحة تسجيل الدخول؟', sender: 'them', time: 'أمس' },
    { id: 'm8', text: 'بالطبع، أرسلت لك الوثائق.', sender: 'me', time: 'أمس' },
    { id: 'm9', text: 'شكراً على المساعدة 🙏', sender: 'them', time: 'أمس' },
  ],
  '4': [
    { id: 'm10', text: 'هل شاهدت الفيلم؟', sender: 'them', time: 'أمس' },
  ],
  '5': [
    { id: 'm11', text: 'أخبرني عندما تكون متفرغاً', sender: 'them', time: 'الإثنين' },
  ],
  '6': [
    { id: 'm12', text: 'إلى اللقاء!', sender: 'them', time: 'الأحد' },
  ],
};

/** Auth tab identifiers */
export const AUTH_TABS = {
  SIGN_IN: 'signin',
  SIGN_UP: 'signup',
};

/** App branding */
export const APP_NAME = 'تطبيق الدردشة';

/** Social login providers shown on the auth form */
export const SOCIAL_PROVIDERS = [
  { id: 'facebook', label: 'f',  className: 'sb-fb', color: '#1877f2', title: 'Facebook' },
  { id: 'google',   label: 'G',  className: 'sb-g',  color: '#ea4335', title: 'Google'   },
  { id: 'twitter',  label: 't',  className: 'sb-tw', color: '#1da1f2', title: 'Twitter'  },
];

/** Content that changes between Sign In and Sign Up tabs */
export const TAB_CONTENT = {
  [AUTH_TABS.SIGN_IN]: {
    formTitle:  'تسجيل الدخول',
    actionBtn:  'تسجيل الدخول',
    sideTitle:  'مرحباً يا صديقي!',
    sideSub:    'سجّل دخولك لمتابعة المحادثة بسهولة',
  },
  [AUTH_TABS.SIGN_UP]: {
    formTitle:  'إنشاء حساب',
    actionBtn:  'إنشاء حساب',
    sideTitle:  'انضم إلينا\nاليوم!',
    sideSub:    'ابدأ دردشة جديدة وابقَ على اتصال مع أصدقائك',
  },
};
